```

4. Create a new Discord client instance and login with your bot token:

```javascript
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.DirectMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.login('YOUR_BOT_TOKEN');
```

5. Define the ban command as a slash command using the `SlashCommandBuilder` class:

```javascript
const data = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bans a user from the server')
  .addUserOption((option) =>
    option
      .setName('user')
      .setDescription('The user to ban')
      .setRequired(true)
  );
```

6. Register the ban command with the Discord client:

```javascript
client.on('ready', () => {
  client.application.commands.create({
    application_id: client.user.id,
    guild_id: 'GUILD_ID',
    data,
  });
});
```

Make sure to replace `GUILD_ID` with the ID of the Discord server where you want to use the bot.

7. Handle the ban command in the `interactionCreate` event:

```javascript
client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { user, member } = interaction;

  if (interaction.commandName === 'ban') {
    if (!member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'You don't have the permission to ban members.',
        ephemeral: true,
      });
    }

    if (member.id === client.user.id) {
      return interaction.reply({
        content: 'I can\'t ban myself.',
        ephemeral: true,
      });
    }

    if (member.id === interaction.user.id) {
      return interaction.reply({
        content: 'You can\'t ban yourself.',
        ephemeral: true,
      });
    }

    await member.ban();

    return interaction.reply({
      content: `${user.tag} has been banned.`,
    });
  }
});
