        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    initGameAssets(renderer);

    SDL_Event event;
    Uint32 startTime, currentTime, deltaTime;

    while (running) {
        SDL_PollEvent(&event);

        switch (event.type) {
            case SDL_QUIT:
                running = 0;
                break;
            case SDL_KEYDOWN:
                switch (event.key.keysym.sym) {
                    case SDLK_LEFT:
                        if (snakeDirX != SNAKE_SPEED) {
