                            snakeDirY = SNAKE_SPEED;
                        }
                        break;
                }
                break;
        }

        startTime = SDL_GetTicks();
        updateSnake();
        currentTime = SDL_GetTicks();
        deltaTime = currentTime - startTime;

        if (deltaTime < 1000 / SNAKE_SPEED) {
            SDL_Delay(1000 / SNAKE_SPEED - deltaTime);
